head.script:
// 화면 리사이징

scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gDate;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    if (js_bond_yn === "Y") {
        // 기타채권공시개발건 20110.08.11
        scwin.gLdMktTp = "4";
    }
    scwin.gDate = edt_SrchDay.getValue();

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 보여준다.
    if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
        if (scwin.gJobTitle === '09' || scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y') {
            // 당번 또는 팀장일 경우에만 보여준다.(2013.10.04) -> 타팀공시 조회 가능때문에 수정함 by LDJ
            panel_2.show("");
        } else {
            panel_2.hide();
        }
    } else {
        panel_2.hide();
    }

    // 현재날짜 셋팅
    // gDate = cGetToday("yyyymmdd");
    edt_SrchDay.setValue($c.ut.cGetToday("yyyymmdd"));

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (scwin.gLdMktTp === '1') {
        txb_noti_msg.setValue('직전 공시일에 [익일]승인처리 된 문서들이 금일 공시개시된 결과입니다.');
        panel_3.hide();
    } else if (scwin.gLdMktTp === '2') {
        txb_noti_msg.setValue('기준일 전일 ~ 기준일 우편함접수 공시 목록입니다.');
        panel_3.show("");
    } else {
        txb_noti_msg.setValue('기준일 전일 ~ 기준일 우편함접수 공시 목록입니다.');
        panel_3.show("");
    }
};

/**
 * @method
 * @name initSearch
 * @description 화면 로딩시 디폴트 검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initSearch = async function() {
    // fn_Search();
    await scwin.checkCond();
};

/**
 * @method
 * @name depListLoadComplete
 * @description dep List Load Complete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.depListLoadComplete = async function() {
    cmb_TeamList.setValue(js_dep_cd);
    // 부서코드 가져온후에  초기검색
    await scwin.initSearch();
};

/**
 * @method
 * @name checkCond
 * @description 일자 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCond = async function() {
    // 일자 체크
    if (edt_SrchDay.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_SrchDay.focus();
        return;
    }
    scwin.gDate = edt_SrchDay.getValue();

    // 유가 공시팀(26**), 코스닥 공시팀(34**) =>  선택부서로
    if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
        scwin.gDepCd = cmb_TeamList.getValue();
        scwin.gEmpNo = cmb_EmpList.getValue();
    } else {
        scwin.gDepCd = ""; // 부서코드 없음 => 전체
        scwin.gEmpNo = "";
    }
    fn_Search();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !우편함공시--;
클릭-- > async function() {
    // 코스닥 시장운영팀을 위하여 추가 수정함.(코스닥 공시가 모두 보여야 함)
    const url = "";
    const sbmOptions = {
        id : "sbm_dts_DsclStatusList",
        action : "/DisclosureStatus.do",
        ref : "",
        target : "dts_DsclStatusList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclStatusList.getCellData(Number(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclStatusList.getCellData(Number(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclStatusList.getCellData(Number(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclStatusList.getCellData(Number(obj), "ISUR_CD");
    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};

/**
 * @method
 * @name dts_DsclStatusList_OnLoadError
 * @description dts_DsclStatusList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclStatusList_OnLoadError = async function() {
    await $c.win.alert(dts_DsclStatusList);
};

/**
 * @method
 * @name dts_DsclStatusList_OnLoadCompleted
 * @description dts_DsclStatusList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclStatusList_OnLoadCompleted = async function(rowcount) {
    if (dts_DsclStatusList.errorMsg) {
        await $c.win.alert(dts_DsclStatusList.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DOC_TITLE") {
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R");
    } else if (colid === "ACPT_DDTM") {
        $c.stf.openDisclAllList();
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀저장」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF10300.xml', SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, {fileName: "우편함공시 목록", type: "2"});
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = async function(rowcount) {
    // setObjectValue(cmb_TeamList, js_dep_cd) ;
    await scwin.depListLoadComplete();
};

/**
 * @method
 * @name dts_emp_OnLoadCompleted
 * @description dts_emp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // setObjectValue(cmb_EmpList, js_emp_no) ;

};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd === '') {
        cmb_EmpList.setValue('');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    // dts_emp.sort(); // W-Craft 주석처리

};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description 부서코드에  해당하는 사원을 가져온다.
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd === "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") === "") {
            return true;
        } else {
            return false;
        }
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    await scwin.checkCond();
};

/**
 * @method
 * @name img_Cal_onclick
 * @description img_Cal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Cal_onclick = function() {
    popUpCalendar2(edt_SrchDay);
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    await scwin.setCode();
    await scwin.initSearch();
};
